WITH department_stats AS (SELECT dept_id, COUNT(CASE WHEN job_title = 'Designer' THEN 1 END) AS designer_count FROM employees WHERE dept_id IN (1, 20, 26, 27) GROUP BY dept_id) SELECT d.location, d.budget, ds.designer_count FROM departments d LEFT JOIN department_stats ds ON d.id = ds.dept_id ORDER BY ds.designer_count DESC
